import React, { useState } from "react";
import { useNavigate, Link } from "react-router-dom";

function RegisterPage() {
  const navigate = useNavigate();
  const [email, setEmail] = useState("");
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [isAdmin, setIsAdmin] = useState(false);
  const [adminSecretKey, setAdminSecretKey] = useState("");
  const [error, setError] = useState("");

  const handleRegister = async (e) => {
    e.preventDefault();
    setError("");

    if (password !== confirmPassword) {
      setError("Паролі не співпадають");
      return;
    }

    if (password.length < 8) {
      setError("Пароль повинен містити мінімум 8 символів");
      return;
    }

    if (isAdmin && !adminSecretKey) {
      setError("Введіть секретний ключ адміністратора");
      return;
    }

    try {
      const body = {
        email,
        password,
        username: username || undefined,
      };

      if (isAdmin && adminSecretKey) {
        body.admin_secret_key = adminSecretKey;
      }

      const res = await fetch("http://127.0.0.1:8000/api/register/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body),
      });

      const data = await res.json();

      if (!res.ok) {
        setError(data.detail || "Помилка реєстрації");
        return;
      }

      localStorage.setItem("token", data.access);
      localStorage.setItem("refresh", data.refresh);
      localStorage.setItem("is_staff", data.user.is_staff);
      localStorage.setItem("is_premium", data.user.is_premium);

      navigate("/");
    } catch (error) {
      console.error("Помилка реєстрації:", error);
      setError("Помилка реєстрації, спробуйте ще раз");
    }
  };

  return (
    <div className="login-container">
      <h2>Реєстрація</h2>
      {error && <div className="error-message">{error}</div>}
      <form onSubmit={handleRegister}>
        <input
          type="email"
          placeholder="Email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          required
        />
        <input
          type="text"
          placeholder="Ім'я користувача (опціонально)"
          value={username}
          onChange={(e) => setUsername(e.target.value)}
        />
        <input
          type="password"
          placeholder="Пароль"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          required
          minLength={8}
        />
        <input
          type="password"
          placeholder="Підтвердити пароль"
          value={confirmPassword}
          onChange={(e) => setConfirmPassword(e.target.value)}
          required
        />
        
        <div style={{ marginTop: "1rem" }}>
          <label style={{ display: "flex", alignItems: "center", gap: "0.5rem" }}>
            <input
              type="checkbox"
              checked={isAdmin}
              onChange={(e) => setIsAdmin(e.target.checked)}
            />
            <span>Створити адміністраторський акаунт</span>
          </label>
        </div>

        {isAdmin && (
          <div style={{ marginTop: "1rem" }}>
            <input
              type="password"
              placeholder="Секретний ключ адміністратора"
              value={adminSecretKey}
              onChange={(e) => setAdminSecretKey(e.target.value)}
              required={isAdmin}
            />
            <small style={{ display: "block", marginTop: "0.25rem", color: "#666" }}>
              Введіть секретний ключ для створення адміністраторського акаунта
            </small>
          </div>
        )}

        <button type="submit">Зареєструватися</button>
      </form>
      <p style={{ marginTop: "1rem", textAlign: "center" }}>
        Вже є акаунт? <Link to="/login">Увійти</Link>
      </p>
    </div>
  );
}

export default RegisterPage;
